function styleStoryInitial(paragraph) {
  const text = document.createTreeWalker(paragraph, NodeFilter.SHOW_TEXT);
  for (let node = text.nextNode(); node; node = text.nextNode()) {
    const letter = node.data.match(/\p{L}\p{M}*/u);
    if (!letter) continue;
    const character = letter[0].normalize('NFC');
    const [base, mark] = character.normalize('NFD');
    const original = sagaInitials[character];
    const glyph = original ?? sagaInitials[base];
    if (!glyph) return;

    const ns = 'http://www.w3.org/2000/svg';
    const initial = document.createElement('span');
    initial.className = 'sm-initial';
    const spoken = document.createElement('span');
    spoken.className = 'sm-initial-text';
    spoken.textContent = letter[0];
    const svg = document.createElementNS(ns, 'svg');
    const [left, top, width, height] = glyph.box.split(' ').map(Number);
    const accent = !original && mark && sagaAccents[mark];
    const below = mark === '\u0327';
    const extra = accent ? 9 : 0;
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('focusable', 'false');
    svg.setAttribute('viewBox', [left, top - (below ? 0 : extra), width, height + extra].join(' '));
    svg.setAttribute('width', glyph.width);
    svg.setAttribute('height', glyph.height + extra);
    const outline = document.createElementNS(ns, 'path');
    outline.setAttribute('d', glyph.path);
    outline.setAttribute('fill-rule', glyph.fill);
    svg.append(outline);
    if (accent) {
      const detail = document.createElementNS(ns, 'path');
      detail.setAttribute('d', accent);
      detail.setAttribute('transform', 'translate(' + (left + width / 2) + ' ' + (below ? top + height : top - 3) + ')');
      detail.setAttribute('fill', 'none');
      detail.setAttribute('stroke', 'currentColor');
      detail.setAttribute('stroke-width', '2.5');
      detail.setAttribute('stroke-linecap', 'round');
      svg.append(detail);
    }
    initial.append(spoken, svg);
    const tail = node.splitText(letter.index);
    tail.deleteData(0, letter[0].length);
    tail.before(initial);
    return;
  }
}
