function countStoryWords(text) {
  const plain = text.replace(/(?<!\\)\*([^*\n]+?)(?<!\\)\*/g, '$1');
  return (plain.match(/[\p{L}\p{N}][\p{L}\p{M}\p{N}]*(?:[-'’][\p{L}\p{N}][\p{L}\p{M}\p{N}]*)*/gu) ?? []).length;
}

const initialTechniques = [{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: Livre, respeitando o custo de manutenção.\nDescrição: O usuário produz cópias ilusórias de sua própria aparência. As duplicatas não possuem substância física e servem para confundir a observação do adversário, sem executar ataques nem interagir materialmente com o cenário.\n\n— Pode criar até 3 cópias simultâneas.\n— A ativação é suplementar e não consome uma ação de combate. A manutenção consome 20 CK por round em que as cópias permanecerem ativas.\n— As cópias podem reproduzir movimentos distintos dos realizados pelo usuário, mas não possuem autonomia real nem podem causar danos.\n— Enquanto as cópias permanecerem ativas e forem relevantes para confundir o adversário, o usuário recebe +1 nos testes de acerto. Esse bônus não se multiplica pela quantidade de cópias.\n— O usuário pode se deslocar fisicamente entre as imagens para dificultar sua identificação, mas não pode trocar instantaneamente de posição com uma cópia.\n— Um adversário que disponha de meios de distinguir imagens incorpóreas poderá reduzir ou neutralizar a vantagem, conforme as regras de detecção e a narrativa.","name":"Bunshin no Jutsu","range":"","rank":"E","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: 1 por ponto de Inteligencia, por combate.\nAlcance: Objeto preparado a até 10 metros.\nDescrição: Técnica de substituição preparada antecipadamente, pela qual o usuário aproveita um objeto próximo para simular que recebeu um ataque e se reposicionar. Não se trata de teletransporte, nem cria imunidade automática a qualquer ameaça.\n\n— O uso deve ser preparado em um round anterior ao da substituição. Durante a preparação, o jogador identifica o objeto que será utilizado, localizado a até 10 metros.\n— Quando o personagem seria atingido por um ataque válido, poderá ativar a substituição gastando uma ação defensiva do round. A ativação dispensa uma nova ação de preparação.\n— Pode responder a ataques físicos e técnicas de até Rank B, desde que haja condição narrativa de substituição e que o personagem ainda possa agir. Não protege contra efeitos de área que também alcancem sua nova posição.\n— Cada personagem dispõe de 1 uso por ponto de Inteligência a cada combate, respeitado o máximo decorrente de seus atributos.\n— Depois de se reposicionar, poderá realizar um teste de Furtividade, quando possuir condições para se ocultar; caso não obtenha sucesso, o adversário identifica sua nova posição.\n— A técnica não pode ser preparada retrospectivamente após o ataque adversário ser anunciado.","name":"Kawarimi no Jutsu","range":"Objeto preparado a até 10 metros.","rank":"E","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Defensiva"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: Ilimitado, enquanto houver condições para sustentá-la.\nDescrição: Exercício fundamental de Controle de Chakra que concentra energia nos pés para manter aderência a árvores, paredes e outras superfícies inclinadas ou verticais.\n\n— Em condições normais, permite caminhar ou permanecer sobre superfícies sólidas adequadas sem testes adicionais.\n— Após consumir mais de 50% do CK máximo do personagem, a manutenção passa a custar 30 CK por uso/round de manutenção.\n— Quando o personagem tiver consumido 80% ou mais do CK máximo, não poderá iniciar nem manter a técnica.\n— Superfícies especiais, ataques e interrupções de concentração continuam sujeitos às regras gerais do confronto.","name":"Kinobori Shūgyō","range":"","rank":"E","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: Ilimitado, enquanto houver condições para sustentá-la.\nDescrição: Técnica de Controle de Chakra que mantém um fluxo equilibrado de energia sob os pés, permitindo ao usuário sustentar-se e deslocar-se pela superfície da água e de outros líquidos compatíveis.\n\n— Em condições normais, permite caminhar ou permanecer sobre superfícies líquidas sem teste adicional para evitar afundar.\n— Após consumir mais de 50% do CK máximo, a manutenção passa a custar 30 CK por uso/round de manutenção.\n— Quando o personagem tiver consumido 80% ou mais do CK máximo, não poderá iniciar nem manter a técnica.\n— A técnica não torna o líquido sólido, não protege contra perigos presentes nele e não impede que impactos ou interrupções comprometam a sustentação.","name":"Suimen Hokō no Gyō","range":"","rank":"E","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: Ilimitado.\nDescrição: Técnica de transformação que altera a aparência externa do usuário para reproduzir a forma de outra pessoa, animal ou objeto dentro das proporções permitidas. A mudança não concede as propriedades, capacidades ou resistência física daquilo que foi imitado.\n\n— As formas assumidas devem possuir entre 1 e 2 metros de dimensão predominante, não sendo possível transformar-se em objetos minúsculos ou criaturas gigantescas.\n— A transformação não concede acesso a Kekkei Genkai, atributos, técnicas, armas naturais nem outras habilidades do modelo copiado.\n— A técnica é desfeita quando o usuário sofre dano ou perde a concentração necessária à sua sustentação.\n— O Henge não substitui automaticamente testes de infiltração ou disfarce quando outros personagens tiverem motivos e meios para investigar a aparência.","name":"Henge no Jutsu","range":"","rank":"E","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: 2 vezes por combate.\nDescrição: O personagem exterioriza uma intenção assassina intensa e ameaçadora, buscando provocar medo e hesitação em adversários menos preparados para suportar sua presença.\n\n— O aplicador realiza um teste com um atributo social apropriado ou outro atributo que represente de forma convincente a ameaça narrada. O alvo resiste com Força de Vontade + 1D10.\n— Somente poderá afetar personagens de Nível inferior ao do usuário ou que possuam Força de Vontade pelo menos 2 pontos abaixo da do aplicador.\n— Em caso de sucesso, aplica Paralisia, respeitando os limites do efeito.\n— O alvo pode tentar superar o medo através de Força de Vontade + 1D10 contra dificuldade 10, em uma oportunidade de reação permitida pelo combate.\n— Também poderá romper a paralisia ao sofrer mais de 60 pontos de dano físico real; essa opção somente pode ser explorada a partir do round seguinte à aplicação, de modo que exista pelo menos um round sob o efeito.\n— O emprego da técnica exige uma intenção de ameaça genuína e coerente com a personalidade e as circunstâncias da cena. A restrição antiga por alinhamento moral fica pendente de confirmação, pois a classificação “caótico neutro ou superior” não define uma progressão inequívoca de alinhamentos.","name":"Sakki no Jutsu","range":"","rank":"E","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar / Controle"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: Ilimitado.\nDescrição: Técnica de fuga ensinada na Academia Ninja, baseada em movimentos corporais e controle preciso de chakra para afrouxar e escapar de cordas ou amarras convencionais.\n\n— Para se libertar, o usuário realiza Controle de Chakra + 1D10 e precisa atingir a dificuldade 6.\n— Funciona apenas contra cordas e amarras convencionais. Não rompe correntes, aprisionamentos especiais ou técnicas de contenção baseadas em chakra.\n— Exige que o personagem ainda possua alguma liberdade física e condições narrativas de executar a manobra; não significa escapar automaticamente de qualquer restrição.","name":"Nawanuke no Jutsu","range":"","rank":"E","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: 2 vezes por combate.\nAlcance: Até 15 metros.\nDescrição: O usuário concentra chakra para realizar um deslocamento veloz e repentino. Embora possa parecer um teletransporte aos observadores, o personagem percorre fisicamente a distância.\n\n— O deslocamento máximo é de 15 metros por utilização.\n— O uso substitui a locomoção convencional do personagem no momento da execução e consome 1 ação.\n— Quando empregado defensivamente para evitar um ataque, exige sucesso no teste de Percepção pertinente à defesa, além do gasto da ação correspondente.\n— Não atravessa barreiras sólidas, não permite passar por espaços fisicamente impossíveis e não supera automaticamente técnicas que atinjam toda a área de destino.","name":"Shunshin no Jutsu","range":"Até 15 metros.","rank":"D","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar / Movimentação"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: 2 vezes por combate.\nSelos: Tigre, com uma mão.\nAlcance: 8 metros.\nDescrição: Por meio de pressão de chakra e intenção intimidatória, o usuário busca imobilizar o corpo de um ou mais adversários, comprometendo temporariamente suas ações de movimento.\n\n— Pode afetar até 3 alvos simultaneamente, desde que cada um esteja dentro do alcance.\n— Aplica Paralisia durante 1 round sobre os alvos que não resistirem à técnica.\n— Somente poderá afetar personagens com Controle de Chakra inferior ao do aplicador ou com reserva máxima de CK inferior a 300.\n— Para cada 100 pontos completos de vantagem de CK máximo que o aplicador possuir sobre um alvo, recebe +1 no modificador de aprisionamento contra aquele alvo. Vantagem parcial não gera bônus.\n— Os testes de aplicação e resistência seguem a regra geral de confronto entre técnicas, com resultados resolvidos individualmente para cada alvo. A técnica não estabelece vitória automática apenas pelo requisito de CK.","name":"Kanashibari no Jutsu","range":"8 metros.","rank":"D","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"Tigre, com uma mão.","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar / Controle"},{"art":"Ninjutsu","cd":"","cost":"Aquisição inicial gratuita. Uso: conforme a descrição e as regras gerais.","description":"Limite de Uso: Ilimitado, respeitando custos, ações e demais condições.\nDescrição: Procedimento de liberação de Genjutsu por interrupção ou reajuste do fluxo de chakra. Pode ser realizado pelo próprio alvo, quando identifica que está sob uma ilusão, ou por um aliado em condições de prestar auxílio.\n\n— Segue integralmente as regras de Aplicação, Identificação e Dissipação estabelecidas no Sistema de Genjutsu.\n— A utilização consciente pelo próprio alvo exige identificação prévia da ilusão, salvo exceção expressa de uma habilidade específica.\n— O teste individual de dissipação é realizado com Controle de Chakra + modificadores + 1D10 contra a dificuldade da ilusão.\n— O custo básico em CK toma como referência o custo da técnica a ser desfeita, aplicando os descontos de Controle de Chakra previstos no Sistema de Genjutsu.\n— O auxílio externo depende de contato ou alcance apropriado, da disponibilidade de uma ação e das condições específicas da ilusão; não oferece libertação automática de toda e qualquer técnica.\n— Jinchūrikis ou outras habilidades capazes de interromper o fluxo de chakra de maneira especial devem seguir suas regras próprias.","name":"Genjutsu Kai","range":"","rank":"—","requirements":"Técnica básica inicial; respeitar as condições individuais de uso.","seals":"","source":"Formação inicial — https://nsc-rpg.forumeiros.com/t8-regra-aquisicao-de-jutsus","type":"Suplementar"},{"art":"Ninjutsu","cd":"3","cost":"CK","description":"A Satetsu se concentra em finas agulhas que avançam rapidamente contra um alvo, atingindo com precisão e deixando resíduos ferrosos presos ao tecido ou à roupa.\n— Em caso de acerto, aplica 2 Marcas Ferríferas.","name":"Satetsu: Tetsubari — Agulhas de Ferro","range":"15 metros","rank":"C","requirements":"Clã Tetsumori","seals":"","source":"Inicial de Clã","type":"Ofensiva"},{"art":"Ninjutsu","cd":"3","cost":"CK","description":"Uma nuvem metálica se comprime em uma placa de areia de ferro, interceptando um ataque percebido. Pode receber os benefícios do Modo Compactado mediante seu custo.","name":"Satetsu: Kurogane no Tate — Escudo de Limalha","range":"5 metros","rank":"C","requirements":"Clã Tetsumori","seals":"","source":"Inicial de Clã","type":"Defensiva"},{"name":"Satetsu: Kōtetsu no Ori — Jaula de Ferro","rank":"B","art":"Ninjutsu","type":"Suplementar/Ofensiva","range":"15 metros","seals":"","cost":"CK","cd":"3","requirements":"Tetsumori","source":"","description":"Barras e filetes de Satetsu se entrelaçam ao redor do adversário, formando uma contenção porosa e difícil de atravessar sem romper a estrutura.\n— Se houver contato efetivo com o alvo durante a captura, aplica 1 Marca Ferrífera."},{"name":"Satetsu: Kurogane no Ame — Chuva Negra","rank":"B","art":"Ninjutsu","type":"Ofensiva","range":"20 metros","seals":"","cost":"CK","cd":"3","requirements":"Tetsumori","source":"","description":"A areia de ferro é dispersa acima da área designada e precipita como uma chuva de pequenos fragmentos agudos. O objetivo é forçar o deslocamento e deixar partículas sobre aqueles que forem atingidos.\n— Aplica 1 Marca Ferrífera por alvo atingido, independentemente da quantidade de fragmentos que o alcance."},{"name":"Satetsu: Kyūin no Kusari — Correntes Sifonadoras","rank":"B","art":"Ninjutsu","type":"Ofensiva/Suplementar","range":"12 metros","seals":"","cost":"","cd":"","requirements":"","source":"Dobra Elemental Satetsu; Vertente de Absorção de Chakra, Contenção de Chakra.","description":"Cordões de limalha se prendem à região atingida do adversário e conduzem a energia absorvida de volta ao usuário, convertendo a areia aderida em um elo temporário de sifonagem.\n— Em caso de acerto, aplica 1 Marca Ferrífera.\n— Enquanto a corrente permanecer sustentada e conectada, o usuário pode recuperar até 20 CK por round retirados do alvo por essa técnica, sem exceder a quantidade efetivamente absorvida.\n— A absorção ativa da corrente não se soma à drenagem das Marcas no mesmo round: considera-se o maior valor aplicável, para não cobrar o mesmo chakra duas vezes.\n— Romper o contato encerra a recuperação ativa, mas as partículas ainda aderidas podem manter as Marcas."}];
const sheetUrl = 'https://nsc-rpg.forumeiros.com/t135-ficha-saga';
const syncOrigin = new URL(sheetUrl).origin;
const jutsuStorage = 'nsc:saga-template-studio:jutsus:v1';
const jutsuChoices = document.querySelector('#jutsu-choices');
const syncStatus = document.querySelector('#jutsu-status');
const jutsuInput = document.querySelector('#jutsu-input');
const techniqueFields = [
  ['art', 'Arte'], ['type', 'Classe'], ['range', 'Alcance'], ['seals', 'Selos'],
  ['cost', 'Custo'], ['cd', 'CD'], ['requirements', 'Requisitos'], ['source', 'Origem']
];
let techniques = initialTechniques;
let chosen = new Set();
let sheetWindow;
try {
  const old = JSON.parse(localStorage.getItem(jutsuStorage));
  if (old) {
    techniques = normalizeTechniques([
      ...initialTechniques.filter(initial => !old.techniques.some(saved => saved.name.trim() === initial.name.trim())),
      ...old.techniques
    ]);
    chosen = new Set(old.chosen);
  }
} catch {}

function normalizeTechniques(records) {
  if (!Array.isArray(records) || !records.length) throw Error('Nenhuma técnica encontrada.');
  const keys = ['name', 'rank', 'description', ...techniqueFields.map(([key]) => key)];
  const unique = new Map();
  for (const entry of records) {
    if (!entry || typeof entry.name !== 'string' || !entry.name.trim()) continue;
    const clean = Object.fromEntries(keys.map(key => [key, typeof entry[key] === 'string' ? entry[key].trim() : '']));
    unique.set(clean.name, clean);
  }
  if (!unique.size) throw Error('Nenhuma técnica encontrada.');
  return [...unique.values()];
}

function saveTechniques() {
  try {
    localStorage.setItem(jutsuStorage, JSON.stringify({ techniques, chosen: [...chosen] }));
  } catch {}
}

function updateTechniqueChoices() {
  const rows = techniques.map(technique => {
    const label = document.createElement('label');
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = chosen.has(technique.name);
    input.addEventListener('change', () => {
      if (input.checked) chosen.add(technique.name);
      else chosen.delete(technique.name);
      saveTechniques();
      render();
    });
    label.append(input, technique.name + (technique.rank && technique.rank !== '—' ? ' · Rank ' + technique.rank : ''));
    return label;
  });
  jutsuChoices.replaceChildren(...rows);
}

function renderJutsus(post) {
  const list = post.querySelector('.sm-jutsu-list');
  const opened = new Set([...list.querySelectorAll('details[open]')].map(item => item.querySelector('.sm-jutsu-name').textContent));
  const cards = techniques.filter(item => chosen.has(item.name)).map(item => {
    const card = document.createElement('details');
    card.className = 'sm-jutsu-entry';
    card.open = opened.has(item.name);
    const title = document.createElement('summary');
    const name = document.createElement('span');
    name.className = 'sm-jutsu-name';
    name.textContent = item.name;
    title.append(name);
    if (item.rank && item.rank !== '—') {
      const rank = document.createElement('span');
      rank.className = 'sm-jutsu-rank';
      rank.textContent = 'Rank ' + item.rank;
      title.append(rank);
    }
    const body = document.createElement('div');
    body.className = 'sm-jutsu-body';
    for (const [key, label] of techniqueFields) {
      if (!item[key]) continue;
      const row = document.createElement('p');
      const heading = document.createElement('b');
      heading.textContent = label + ' ';
      row.append(heading, item[key]);
      body.append(row);
    }
    if (item.description) {
      const description = document.createElement('div');
      appendLines(description, item.description);
      body.append(description);
    }
    card.append(title, body);
    return card;
  });
  list.replaceChildren(...cards);
}

function importTechniques(records) {
  const fresh = normalizeTechniques(records);
  techniques = fresh;
  chosen = new Set(fresh.filter(item => chosen.has(item.name)).map(item => item.name));
  updateTechniqueChoices();
  saveTechniques();
  render();
  syncStatus.textContent = fresh.length + ' técnicas carregadas da ficha.';
}

function copyFromSheet() {
  if (location.origin !== 'https://nsc-rpg.forumeiros.com' || !/^\/t135-ficha-saga(?:-|$)/.test(location.pathname)) {
    alert('Abra o tópico da ficha do Saga antes de usar este favorito.');
    return;
  }
  try {
    const frame = document.querySelector('iframe[title="Ficha de Saga"]');
    const hash = new URL(frame.src).hash.slice(1);
    const encoded = new URLSearchParams(hash).get('sc-view').replace(/-/g, '+').replace(/_/g, '/');
    const data = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(encoded), char => char.charCodeAt(0))));
    if (!Array.isArray(data.jutsus) || !data.jutsus.length) throw Error();
    if (window.opener) {
      window.opener.postMessage({ type: 'saga-sheet-jutsus', techniques: data.jutsus }, '*');
      return;
    }
    const payload = JSON.stringify(data.jutsus);
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(payload).then(
        () => alert('Jutsus copiados. Cole no campo de importação do estúdio.'),
        () => prompt('Copie os jutsus e cole no campo de importação do estúdio.', payload)
      );
    } else {
      prompt('Copie os jutsus e cole no campo de importação do estúdio.', payload);
    }
  } catch {
    alert('O pergaminho ainda não carregou. Aguarde a ficha aparecer e tente novamente.');
  }
}

const syncBookmark = document.querySelector('#sync-bookmark');
syncBookmark.href = 'javascript:' + encodeURIComponent('(' + copyFromSheet.toString() + ')()');
syncBookmark.addEventListener('click', event => {
  event.preventDefault();
  syncStatus.textContent = 'Arraste este atalho para a barra de favoritos e use-o na aba da ficha.';
});
document.querySelector('#open-sheet').addEventListener('click', () => {
  sheetWindow = window.open(sheetUrl, '_blank');
  if (!sheetWindow) syncStatus.textContent = 'O navegador bloqueou a nova aba. Permita a abertura de novas abas e tente novamente.';
});
window.addEventListener('message', event => {
  if (event.origin !== syncOrigin || event.source !== sheetWindow || event.data?.type !== 'saga-sheet-jutsus') return;
  try { importTechniques(event.data.techniques); }
  catch { syncStatus.textContent = 'A ficha retornou uma lista inválida.'; }
});
document.querySelector('#import-jutsu').addEventListener('click', () => {
  try {
    importTechniques(JSON.parse(jutsuInput.value));
    jutsuInput.value = '';
  } catch { syncStatus.textContent = 'Cole a lista copiada pelo favorito e tente novamente.'; }
});
updateTechniqueChoices();

function render() {
  const open = preview.querySelector('.sm-field:not(.sm-jutsus)')?.open ?? false;
  let post = preview.firstElementChild;
  if (!post) {
    post = template.content.firstElementChild.cloneNode(true);
    post.querySelector('.sm-hero').addEventListener('click', fireSatetsu);
    preview.append(post);
  }
  for (const [selector, field] of controls) {
    const node = post.querySelector(selector);
    const value = field.value.trim();
    if (selector === '.sm-name') {
      const letters = Array.from(new Intl.Segmenter('pt-BR', { granularity: 'grapheme' }).segment(value), item => item.segment);
      const fragment = document.createDocumentFragment();
      for (const letter of letters) {
        if (!letter.trim()) {
          fragment.append(letter);
          continue;
        }
        const target = document.createElement('button');
        target.type = 'button';
        target.className = 'sm-letter';
        target.textContent = letter;
        fragment.append(target);
      }
      node.replaceChildren(fragment);
    } else if (selector === '.sm-note-text') {
      node.replaceChildren();
      for (const [index, line] of value.split('\n').entries()) {
        if (index) node.append(document.createElement('br'));
        node.append(line);
      }
    } else {
      node.textContent = value;
    }
  }
  const parts = story.value.trim().split(/(\n(?:[\t ]*\n)+)/);
  const paragraphs = document.createDocumentFragment();
  for (const [index, part] of parts.entries()) {
    if (index % 2 === 1) {
      const extraLines = part.split('\n').length - 3;
      if (extraLines > 0) {
        const gap = document.createElement('div');
        gap.setAttribute('aria-hidden', 'true');
        gap.style.height = (extraLines * 1.85) + 'em';
        paragraphs.append(gap);
      }
    } else if (part) {
      const paragraph = document.createElement('p');
      appendStoryParagraph(paragraph, part);
      if (index === 0) styleStoryInitial(paragraph);
      paragraphs.append(paragraph);
    }
  }
  post.querySelector('.sm-prose').replaceChildren(paragraphs);
  const notes = post.querySelector('.sm-field:not(.sm-jutsus)');
  post.querySelector('.sm-word-count').textContent = countStoryWords(story.value).toLocaleString('pt-BR');
  notes.open = open;
  renderRP(post);
  renderJutsus(post);
  return post;
}

document.querySelector('.editor').addEventListener('input', () => {
  render();
  fallback.hidden = true;
  status.textContent = '';
  try {
    const draft = Object.fromEntries(Array.from(controls, ([key, input]) => [key, input.value]));
    localStorage.setItem(storageKey, JSON.stringify({ ...draft, story: story.value, rpType: rpSelect.value }));
  } catch {}
});

document.querySelector('#copy').addEventListener('click', async () => {
  const post = render().cloneNode(true);
  const fire = document.createElement('button');
  fire.type = 'button';
  fire.className = 'sm-forum-fire';
  fire.setAttribute('aria-label', 'Disparar no banner');
  post.querySelector('.sm-hero').prepend(fire);
  post.querySelectorAll('details[open]').forEach(item => { item.open = false; });
  for (const letter of post.querySelectorAll('.sm-letter')) {
    const target = document.createElement('details');
    target.className = 'sm-forum-letter';
    const summary = document.createElement('summary');
    const glyph = document.createElement('span');
    glyph.className = 'sm-glyph';
    glyph.textContent = letter.textContent;
    summary.append(glyph);
    target.append(summary);
    letter.replaceWith(target);
  }
  post.querySelectorAll('.sm-pellet, .sm-recoil').forEach(effect => effect.remove());
  post.querySelector('.sm-hero').classList.remove('sm-recoiling');
  post.querySelectorAll('[data-sat-hit]').forEach(letter => letter.removeAttribute('data-sat-hit'));
  const code = '<style>' + postCSS.trim() + '</style>' + post.outerHTML.replace(/\r?\n/g, ' ');
  try {
    await navigator.clipboard.writeText(code);
    fallback.hidden = true;
    status.textContent = 'Código copiado. Cole no modo fonte do Forumeiros.';
  } catch {
    fallback.value = code;
    fallback.hidden = false;
    fallback.select();
    status.textContent = 'Código selecionado. Pressione Ctrl+C para copiar.';
  }
});
render();
